solution_code:
def safe_divide(a, b):
    if not isinstance(a, (int, float)) or not isinstance(b, (int, float)):
        raise ValueError("Both inputs must be numbers")
    return a / b

test_suite:
def test_normal_division():
    result = exercise.safe_divide(10, 2)
    assert result == 5.0, f"Expected 5.0, got {result}"

def test_division_float():
    result = exercise.safe_divide(7, 2)
    assert result == 3.5, f"Expected 3.5, got {result}"

def test_division_by_negative():
    result = exercise.safe_divide(10, -2)
    assert result == -5.0, f"Expected -5.0, got {result}"

def test_division_by_zero():
    try:
        exercise.safe_divide(10, 0)
        assert False, "Expected ZeroDivisionError for denominator=0, but no exception was raised"
    except ZeroDivisionError:
        pass

def test_non_numeric_numerator():
    try:
        exercise.safe_divide("hello", 5)
        assert False, "Expected ValueError for non-numeric input, but no exception was raised"
    except ValueError as e:
        assert "Both inputs must be numbers" in str(e), f"Expected message about numbers, got {str(e)!r}"

def test_non_numeric_denominator():
    try:
        exercise.safe_divide(10, "x")
        assert False, "Expected ValueError for non-numeric input, but no exception was raised"
    except ValueError as e:
        assert "Both inputs must be numbers" in str(e), f"Expected message about numbers, got {str(e)!r}"

