solution_code:
def check_age(age):
    if age < 0 or age > 150:
        raise ValueError("Age must be 0-150")
    return "Age is valid"

test_suite:
def test_valid_age():
    result = exercise.check_age(25)
    assert result == "Age is valid", f"Expected 'Age is valid', got {result!r}"

def test_boundary_low():
    result = exercise.check_age(0)
    assert result == "Age is valid", f"Expected 'Age is valid' for 0, got {result!r}"

def test_boundary_high():
    result = exercise.check_age(150)
    assert result == "Age is valid", f"Expected 'Age is valid' for 150, got {result!r}"

def test_raises_for_negative():
    try:
        exercise.check_age(-1)
        assert False, "Expected ValueError for -1, but no exception was raised"
    except ValueError as e:
        assert "Age must be 0-150" in str(e), f"Expected message 'Age must be 0-150', got {str(e)!r}"

def test_raises_for_too_old():
    try:
        exercise.check_age(151)
        assert False, "Expected ValueError for 151, but no exception was raised"
    except ValueError as e:
        assert "Age must be 0-150" in str(e), f"Expected message 'Age must be 0-150', got {str(e)!r}"

