    # Try to open and read the file; if not found, create it with "New file!"
    pass

solution_code:
def read_or_create(filename):
    try:
        with open(filename, "r") as f:
            return f.read()
    except FileNotFoundError:
        with open(filename, "w") as f:
            f.write("New file!")
        return "New file!"
